independence_wave_transform_league_charter = {
	name = independence_wave_transform_league_charter
	desc = independence_wave_transform_league_charter_desc
	icon = GFX_decision_independence_wave_league_votes
	activation = {
		can_independence_wave_use_high_chaos_actions = yes
		is_independence_wave_charter_compliant_member = yes
		NOT = { has_global_flag = independence_wave_radical_charter_active }
		NOT = { has_country_flag = independence_wave_radical_charter_transformed }
		NOT = { has_country_flag = independence_wave_dm59_charter_vote_failed }
		NOT = { has_independence_wave_active_league_crisis = yes }
		OR = {
			var:global.independence_wave_league_leader = { tag = ROOT }
			var:global.independence_wave_congress_leader = { tag = ROOT }
			has_country_flag = independence_wave_league_founder
		}
	}
	selectable_mission = yes
	available = {
		can_pay_independence_wave_strategic_cost = yes

war_propaganda = { 

	icon = generic_prepare_civil_war

	available = {
		NOT = { has_country_flag = war_propaganda_campaign_running }
		has_war_support < 0.5

		if = {
			limit = {
				tag = SPR
				has_dlc = "La Resistance"
			}
			NOT = {
				has_idea = SPR_political_violence
			}
		}
		if = {
			limit = {
				original_tag = SPR
				has_dlc = "La Resistance"
			}
			has_global_flag = scw_over
		}
	}

	visible = {
		OR = {
			has_war_with_non_exiled_country = yes  
			any_neighbor_country = {
				AND = {
					NOT = { has_government = ROOT }
					has_offensive_war = yes
					has_added_tension_amount > 10
				}
			}
		}
	}

	fire_only_once = no

	days_remove = 90
	days_re_enable = 180

	cost = 150

	modifier = {
		war_support_weekly = 0.005
	}

	complete_effect = {
		set_country_flag = war_propaganda_campaign_running
	}
	remove_effect = {
		clr_country_flag = war_propaganda_campaign_running
	}

	ai_will_do = {
		base = 0
		modifier = {
			add = 1
			has_war_support < 0.4
			has_war = yes
		}
	}
}

custom_cost_trigger = { can_pay_independence_wave_strategic_cost = yes }
custom_cost_text = independence_wave_cost_strategic
modifier = { civilian_factory_use = @CR_SC_INDEPENDENCE_WAVE_DECISION_COST_CIVILIAN_FACTORY_STANDARD }
days_remove = constant:independence_wave_decision_duration.long
days_mission_timeout = constant:independence_wave_decision_duration.long
complete_effect = {
	if = {
		limit = { NOT = { has_global_flag = independence_wave_radical_charter_active } }
		independence_wave_decision_pay_strategic = yes
		set_country_flag = independence_wave_radical_charter_transformed
		set_global_flag = independence_wave_radical_charter_active
		set_variable = { global.independence_wave_league_route = constant:independence_wave_league_route.radical_revisionist }
		independence_wave_record_revisionist_action = yes
