		# removes the current member from the live registry; iterating that same
		# array would shift the next row into the cursor and skip low-standing
		# members who must depart under the transformed charter.
		clear_temp_array = independence_wave_radical_charter_member_entries
		for_each_scope_loop = {
			array = global.independence_wave_league_member_country_entries
			add_to_temp_array = { array = independence_wave_radical_charter_member_entries value = THIS }
		}
